# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student


def make(last, first):
    return Student(last + first, last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        people = [
            make("Halloway", "Juno"),
            make("Zed", "Amy"),
            make("Dunmere", "Piet")
        ]
        self.assertEqual(
            seat_rows(people, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zed, Amy"
            ]
        )

    def test_first_name_breaks_ties(self):
        people = [make("Lee", "Zoe"), make("Lee", "Al")]
        self.assertEqual(
            seat_rows(people, 5),
            ["Row 1: Lee, Al | Lee, Zoe"]
        )

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([make("A", "B")], 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([make("A", "B")], -3)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)
